const knownLocale = (id) => LOCALES.some((item) => item.id === id);
let active = 'en';

export function initLocale() {
  try {
    const saved = localStorage.getItem('mth-locale');
    if (knownLocale(saved)) active = saved;
  } catch { /* storage may be blocked */ }
  document.documentElement.lang = LOCALES.find((item) => item.id === active).tag;
  return active;
}

export function getLocale() { return active; }

export function setLocale(id) {
  if (!knownLocale(id)) return active;
  active = id;
  document.documentElement.lang = LOCALES.find((item) => item.id === active).tag;
  try { localStorage.setItem('mth-locale', active); } catch { /* storage may be blocked */ }
  return active;
}

export function localeOptions() { return LOCALES.map(({ id, name }) => ({ id, name })); }

export function countText(kind, value) {
  const locale = active;
  const rule = new Intl.PluralRules(LOCALES.find((item) => item.id === active).tag).select(value);
  const forms = {
    tool: {
      en: { one: 'tool', other: 'tools' }, pl: { one: 'narzędzie', few: 'narzędzia', many: 'narzędzi', other: 'narzędzia' },
      de: { one: 'Werkzeug', other: 'Werkzeuge' }, uk: { one: 'інструмент', few: 'інструменти', many: 'інструментів', other: 'інструменти' }, zh: { other: '个工具' },
    },
    group: {
      en: { one: 'group', other: 'groups' }, pl: { one: 'kategoria', few: 'kategorie', many: 'kategorii', other: 'kategorie' },
      de: { one: 'Gruppe', other: 'Gruppen' }, uk: { one: 'група', few: 'групи', many: 'груп', other: 'групи' }, zh: { other: '个类别' },
    },
  };
  const word = forms[kind]?.[locale]?.[rule] || forms[kind]?.[locale]?.other || kind;
  return `${formatNumber(value)} ${word}`;
}

export function t(source, values = {}) {
  const index = LOCALES.findIndex((item) => item.id === active) - 1;
  const translated = index < 0 ? source : (phrases[source]?.[index] || source);
  return String(translated).replace(/\{(\w+)\}/g, (_, key) => String(values[key] ?? `{${key}}`));
}

export function applyStaticTranslations(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-placeholder]').forEach((el) => { el.placeholder = t(el.dataset.i18nPlaceholder); });
  root.querySelectorAll('[data-i18n-aria]').forEach((el) => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
  root.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll('[data-i18n-content]').forEach((el) => { el.setAttribute('content', t(el.dataset.i18nContent)); });
}

export function formatNumber(value, options) {
  const tag = LOCALES.find((item) => item.id === active).tag;
  return new Intl.NumberFormat(tag, options).format(value);
}
